/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: SearchResponse, ShellOptions
 *   Functions: artist, album, track, organization, payloadFor, Location, renderWideShell, globalSearch,
 *              combobox, listbox, location, pastNavigationDebounce
 *   Constants: signedInSession
 * Tests
 *   - wide layouts preview one debounced query inline and keep the current route
 *   - arrow keys highlight a result and Enter opens it, records the query, and focuses the page
 *   - ArrowUp wraps to the last suggestion, ArrowDown wraps to the first, and the highlight scrolls into view
 *   - typing after highlighting voids the highlight, so Enter searches what was typed
 *   - results from a previous query are hidden, not selectable, until the new query answers
 *   - the search button always opens full results, even with a hovered suggestion
 *   - opening full results after a preview reuses the previewed response
 *   - Escape closes the suggestions, and a second Escape clears the field without reopening them
 *   - moving focus out of the field closes the suggestions
 *   - arrow keys during IME composition leave the suggestions alone
 *   - a recent search re-runs that query and moves it to the newest position
 *   - a signed-in listener sees and records only their own search history
 *   - a MediaTrack suggestion starts playback, keeps the route, and keeps focus in the field
 *   - suggestions keep a bounded, ordered preview and open Organizations
 *   - an unavailable search endpoint shows its error inside the suggestions
 *   - narrowing the window with a draft in the field does not open Search by itself
 *   - the Search route filters by type and resets the filter for each new query
 *   - a selected filter whose group vanishes after a refetch falls back to All
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter, Route, Routes, useLocation } from 'react-router';

import { browserSessionQueryKey } from '../../api/session';
import { listenerCapabilitiesQueryKey } from '../../api/listenerCapabilities';
import { AppShell } from '../../app/AppShell';
import { playerStore } from '../../player';
import { SearchPage } from './SearchPage';
import { readSearchHistory, rememberSearchQuery } from './searchHistory';

type SearchResponse = { status?: number; body?: unknown; delay?: Promise<void> };

const artist = (id: string, name: string) => ({ contentType: 'artist', id, name, bio: '', artworkUrl: '' });
const album = (id: string, title: string) => ({
  contentType: 'album', id, title, artworkUrl: '', artistNames: ['Night Ensemble'], releaseDate: { year: 2026 }
});
const track = (id: string, title: string) => ({
  contentType: 'audioTrack', id, title, artworkUrl: '', artistNames: ['Night Ensemble'], albumId: 'album-1',
  albumTitle: 'Night Window', duration: '3:00', mediaType: 'audio', streamUrl: `/content/mediaTrack/stream/${id}`
});
const organization = (id: string, name: string) => ({
  contentType: 'organization', id, name, organizationType: 'Label', description: ''
});

/** A payload whose names carry the query, so results from different queries are distinguishable. */
const payloadFor = (query: string) => ({
  query,
  artists: [artist(`artist-${query}`, `${query} Ensemble`)],
  organizations: [],
  albums: [album(`album-${query}`, `${query} Window`)],
  audioTracks: [track(`track-${query}`, `${query} Light`)]
});

/** Reports the router location so tests can prove the typeahead keeps the current route. */
const Location = () => {
  const location = useLocation();
  return <p data-testid="location">{`${location.pathname}${location.search}`}</p>;
};

interface ShellOptions {
  path?: string;
  session?: unknown;
  respond?: (query: string) => SearchResponse;
}

/** Renders the shell on a wide layout (inline typeahead on) with a controllable search endpoint. */
const renderWideShell = ({ path = '/', session = null, respond = (query) => ({ body: payloadFor(query) }) }: ShellOptions = {}) => {
  const layoutListeners = new Set<() => void>();
  const layout = { wide: true };
  vi.stubGlobal('matchMedia', vi.fn((query: string) => ({
    get matches() { return query === '(min-width: 768px)' ? layout.wide : false; },
    addEventListener: (_type: string, listener: () => void) => layoutListeners.add(listener),
    removeEventListener: (_type: string, listener: () => void) => layoutListeners.delete(listener)
  })));
  const searchQueries: string[] = [];
  const fetchMock = vi.fn(async (input: RequestInfo | URL) => {
    const url = new URL(String(input), 'http://localhost');
    if (url.pathname !== '/api/listener/v1/search') {
      return new Response('{}', { status: 200, headers: { 'Content-Type': 'application/json' } });
    }
    const query = url.searchParams.get('q') ?? '';
    searchQueries.push(query);
    const response = respond(query);
    await response.delay;
    return new Response(JSON.stringify(response.body ?? { code: 'unavailable' }), {
      status: response.status ?? 200,
      headers: { 'Content-Type': 'application/json' }
    });
  });
  vi.stubGlobal('fetch', fetchMock);
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  queryClient.setQueryData(browserSessionQueryKey, session);
  queryClient.setQueryData(listenerCapabilitiesQueryKey, { playlists: false });
  render(
    <QueryClientProvider client={queryClient}>
      <MemoryRouter initialEntries={[path]}>
        <Routes>
          <Route element={<AppShell />}>
            <Route index element={<p>Home route content</p>} />
            <Route path="/search" element={<SearchPage />} />
            <Route path="/albums/:albumId" element={<p>Album detail</p>} />
            <Route path="/artists/:artistId" element={<p>Artist detail</p>} />
            <Route path="/organizations/:organizationId" element={<p>Organization detail</p>} />
          </Route>
        </Routes>
        <Location />
      </MemoryRouter>
    </QueryClientProvider>
  );
  const narrow = () => act(() => {
    layout.wide = false;
    layoutListeners.forEach((listener) => listener());
  });
  return { fetchMock, searchQueries, narrow, queryClient };
};

// The shell field is lazy-loaded, so wait for it before querying inside it.
const globalSearch = () => screen.findByRole('search', { name: 'Global search' });
const combobox = async () => within(await globalSearch()).findByRole('combobox');
const listbox = () => screen.findByRole('listbox', { name: 'Search suggestions' });
const location = () => screen.getByTestId('location');
/** Waits past the 300 ms narrow-layout navigation debounce so route assertions are meaningful. */
const pastNavigationDebounce = () => act(() => new Promise((resolve) => setTimeout(resolve, 350)));

const signedInSession = {
  user: {
    id: 'u1', email: 'listener@example.com', role: 'user', displayName: 'Listener',
    avatarRevision: 0, avatar: null, emailVerified: true
  }
};

beforeEach(() => {
  localStorage.clear();
});

test('wide layouts preview one debounced query inline and keep the current route', async () => {
  const user = userEvent.setup();
  const { searchQueries } = renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');

  const list = await listbox();
  expect(field).toHaveAttribute('aria-expanded', 'true');
  expect(field).toHaveAttribute('aria-controls', list.id);
  expect(await within(list).findByRole('option', { name: /Night Window/ })).toBeInTheDocument();
  expect(within(list).getByRole('option', { name: /Search for “Night”/ })).toBeInTheDocument();
  await pastNavigationDebounce();
  expect(location()).toHaveTextContent(/^\/$/);
  expect(screen.getByText('Home route content')).toBeInTheDocument();
  // Character-by-character typing produces one request after the debounce, never one per key.
  expect(searchQueries).toEqual(['Night']);
  expect(readSearchHistory(null)).toEqual([]);
});

test('arrow keys highlight a result and Enter opens it, records the query, and focuses the page', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  const list = await listbox();
  const albumOption = await within(list).findByRole('option', { name: /Night Window/ });

  // Option order: Search for, artist, album.
  await user.keyboard('{ArrowDown}{ArrowDown}{ArrowDown}');
  expect(field).toHaveAttribute('aria-activedescendant', albumOption.id);
  expect(albumOption).toHaveAttribute('aria-selected', 'true');
  await user.keyboard('{Enter}');

  await waitFor(() => expect(location()).toHaveTextContent('/albums/album-Night'));
  expect(readSearchHistory(null)).toEqual(['Night']);
  expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  await waitFor(() => expect(document.activeElement).toBe(document.getElementById('main-content')));
});

test('ArrowUp wraps to the last suggestion, ArrowDown wraps to the first, and the highlight scrolls into view', async () => {
  const user = userEvent.setup();
  const scrollIntoView = vi.fn();
  Element.prototype.scrollIntoView = scrollIntoView;
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  const list = await listbox();
  const options = await within(list).findAllByRole('option');
  await waitFor(() => expect(within(list).getAllByRole('option')).toHaveLength(4));

  await user.keyboard('{ArrowUp}');
  const last = within(list).getAllByRole('option').at(-1)!;
  expect(field).toHaveAttribute('aria-activedescendant', last.id);
  expect(scrollIntoView).toHaveBeenLastCalledWith({ block: 'nearest' });
  await user.keyboard('{ArrowDown}');
  expect(field).toHaveAttribute('aria-activedescendant', within(list).getAllByRole('option')[0].id);
  expect(options.length).toBeGreaterThan(0);
});

test('typing after highlighting voids the highlight, so Enter searches what was typed', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  const list = await listbox();
  await within(list).findByRole('option', { name: /Night Window/ });
  await user.keyboard('{ArrowDown}{ArrowDown}{ArrowDown}');
  expect(field).toHaveAttribute('aria-activedescendant');

  // Enter lands inside the debounce window, before the list is rebuilt for "Nights".
  await user.type(field, 's');
  expect(field).not.toHaveAttribute('aria-activedescendant');
  await user.keyboard('{Enter}');

  await waitFor(() => expect(location()).toHaveTextContent('/search?q=Nights'));
  expect(field).toHaveValue('Nights');
  expect(readSearchHistory(null)).toEqual(['Nights']);
});

test('results from a previous query are hidden, not selectable, until the new query answers', async () => {
  const user = userEvent.setup();
  let release!: () => void;
  const delayed = new Promise<void>((resolve) => { release = resolve; });
  renderWideShell({
    respond: (query) => (query === 'Nightx' ? { body: payloadFor(query), delay: delayed } : { body: payloadFor(query) })
  });

  const field = await combobox();
  await user.type(field, 'Night');
  const list = await listbox();
  await within(list).findByRole('option', { name: /Night Window/ });
  await user.type(field, 'x');

  await within(list).findByRole('option', { name: /Search for “Nightx”/ });
  expect(within(list).queryByRole('option', { name: /Night Window/ })).not.toBeInTheDocument();
  expect(screen.getAllByText('Searching the listening room…').length).toBeGreaterThan(0);
  await user.keyboard('{ArrowDown}');
  const searchFor = within(list).getByRole('option', { name: /Search for “Nightx”/ });
  expect(field).toHaveAttribute('aria-activedescendant', searchFor.id);

  await act(async () => { release(); });
  await within(list).findByRole('option', { name: /Nightx Window/ });
  // The highlight still names the same suggestion after real results arrive.
  expect(field).toHaveAttribute('aria-activedescendant', searchFor.id);
});

test('the search button always opens full results, even with a hovered suggestion', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const form = await globalSearch();
  const field = await combobox();
  await user.type(field, 'Night');
  const list = await listbox();
  const albumOption = await within(list).findByRole('option', { name: /Night Window/ });
  fireEvent.mouseMove(albumOption);
  expect(albumOption).toHaveAttribute('aria-selected', 'true');
  fireEvent.mouseLeave(list);
  expect(albumOption).toHaveAttribute('aria-selected', 'false');
  fireEvent.mouseMove(albumOption);

  await user.click(within(form).getByRole('button', { name: 'Submit search' }));

  await waitFor(() => expect(location()).toHaveTextContent('/search?q=Night'));
  expect(readSearchHistory(null)).toEqual(['Night']);
});

test('opening full results after a preview reuses the previewed response', async () => {
  const user = userEvent.setup();
  const { searchQueries } = renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  await within(await listbox()).findByRole('option', { name: /Night Window/ });
  await user.keyboard('{Enter}');

  expect(await screen.findByRole('heading', { name: 'Results for “Night”' })).toBeInTheDocument();
  expect(searchQueries).toEqual(['Night']);
});

test('Escape closes the suggestions, and a second Escape clears the field without reopening them', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  await listbox();
  await user.keyboard('{Escape}');

  expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  expect(field).toHaveAttribute('aria-expanded', 'false');
  expect(field).toHaveFocus();

  await user.keyboard('{Escape}');
  expect(field).toHaveValue('');
  expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  expect(readSearchHistory(null)).toEqual([]);
});

test('moving focus out of the field closes the suggestions', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  await listbox();
  await user.tab();

  expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  expect(field).toHaveAttribute('aria-expanded', 'false');
});

test('arrow keys during IME composition leave the suggestions alone', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  await within(await listbox()).findByRole('option', { name: /Night Window/ });
  fireEvent.compositionStart(field);
  fireEvent.keyDown(field, { key: 'ArrowDown', isComposing: true });
  fireEvent.keyDown(field, { key: 'Escape', isComposing: true });

  expect(field).not.toHaveAttribute('aria-activedescendant');
  expect(screen.getByRole('listbox', { name: 'Search suggestions' })).toBeInTheDocument();
});

test('a recent search re-runs that query and moves it to the newest position', async () => {
  const user = userEvent.setup();
  rememberSearchQuery(null, 'Piano');
  rememberSearchQuery(null, 'Ambient');
  renderWideShell();

  await user.click(await combobox());
  const list = await listbox();
  expect(within(list).getAllByRole('option').map((option) => option.textContent)).toEqual([
    expect.stringContaining('Ambient'),
    expect.stringContaining('Piano')
  ]);
  await user.click(within(list).getByRole('option', { name: /Piano/ }));

  await waitFor(() => expect(location()).toHaveTextContent('/search?q=Piano'));
  expect(readSearchHistory(null)).toEqual(['Piano', 'Ambient']);
});

test('a signed-in listener sees and records only their own search history', async () => {
  const user = userEvent.setup();
  rememberSearchQuery(null, 'Signed-out query');
  rememberSearchQuery('u1', 'Listener query');
  renderWideShell({ session: signedInSession });

  await user.click(await combobox());
  const list = await listbox();
  expect(within(list).getByRole('option', { name: /Listener query/ })).toBeInTheDocument();
  expect(within(list).queryByRole('option', { name: /Signed-out query/ })).not.toBeInTheDocument();

  await user.type(await combobox(), 'Night');
  await within(list).findByRole('option', { name: /Night Window/ });
  await user.keyboard('{Enter}');

  await waitFor(() => expect(location()).toHaveTextContent('/search?q=Night'));
  expect(readSearchHistory('u1')).toEqual(['Night', 'Listener query']);
  expect(readSearchHistory(null)).toEqual(['Signed-out query']);
});

test('a MediaTrack suggestion starts playback, keeps the route, and keeps focus in the field', async () => {
  const user = userEvent.setup();
  const launch = vi.spyOn(playerStore, 'launchStandalone').mockResolvedValue();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  const list = await listbox();
  await user.click(await within(list).findByRole('option', { name: /Night Light/ }));

  await waitFor(() => expect(launch).toHaveBeenCalledWith(expect.objectContaining({ id: 'track-Night' })));
  expect(location()).toHaveTextContent(/^\/$/);
  expect(field).toHaveFocus();
  expect(readSearchHistory(null)).toEqual(['Night']);
});

test('suggestions keep a bounded, ordered preview and open Organizations', async () => {
  const user = userEvent.setup();
  renderWideShell({
    respond: (query) => ({
      body: {
        query,
        artists: [artist('a1', 'A1'), artist('a2', 'A2'), artist('a3', 'A3')],
        organizations: [organization('o1', 'Org One'), organization('o2', 'Org Two')],
        albums: [album('b1', 'B1'), album('b2', 'B2'), album('b3', 'B3'), album('b4', 'B4')],
        audioTracks: [track('t1', 'T1'), track('t2', 'T2'), track('t3', 'T3'), track('t4', 'T4')]
      }
    })
  });

  await user.type(await combobox(), 'Mix');
  const list = await listbox();
  await within(list).findByRole('option', { name: /Org One/ });
  const titles = within(list).getAllByRole('option').map((option) => option.textContent ?? '');
  expect(titles.map((title) => title.replace(/(Artist|Album|MediaTrack|Label).*$/, ''))).toEqual([
    'Search for “Mix”', 'A1', 'A2', 'B1', 'B2', 'B3', 'T1', 'T2', 'T3', 'Org One'
  ]);
  await user.click(within(list).getByRole('option', { name: /Org One/ }));

  await waitFor(() => expect(location()).toHaveTextContent('/organizations/o1'));
  expect(readSearchHistory(null)).toEqual(['Mix']);
});

test('an unavailable search endpoint shows its error inside the suggestions', async () => {
  const user = userEvent.setup();
  renderWideShell({ respond: () => ({ status: 500 }) });

  await user.type(await combobox(), 'Night');
  const list = await listbox();

  expect((await screen.findAllByText('Search is unavailable right now.')).length).toBeGreaterThan(0);
  expect(within(list).getAllByRole('option')).toHaveLength(1);
});

test('narrowing the window with a draft in the field does not open Search by itself', async () => {
  const user = userEvent.setup();
  const { narrow } = renderWideShell();

  await user.type(await combobox(), 'Night');
  await listbox();
  narrow();
  await pastNavigationDebounce();

  expect(location()).toHaveTextContent(/^\/$/);
  expect(readSearchHistory(null)).toEqual([]);
});

test('the Search route filters by type and resets the filter for each new query', async () => {
  const user = userEvent.setup();
  renderWideShell({ path: '/search?q=Night' });

  const field = await within(await globalSearch()).findByRole('searchbox');
  expect(field).not.toHaveAttribute('aria-expanded');
  expect(await screen.findByRole('heading', { name: 'Results for “Night”' })).toBeInTheDocument();

  const filters = await screen.findByRole('group', { name: 'Search result types' });
  await user.click(within(filters).getByRole('button', { name: 'Albums' }));
  expect(within(filters).getByRole('button', { name: 'Albums' })).toHaveAttribute('aria-pressed', 'true');
  expect(screen.queryByRole('heading', { name: 'Artists' })).not.toBeInTheDocument();

  await user.clear(field);
  await user.type(field, 'Dawn');
  expect(await screen.findByRole('heading', { name: 'Results for “Dawn”' })).toBeInTheDocument();
  const dawnFilters = await screen.findByRole('group', { name: 'Search result types' });
  expect(within(dawnFilters).getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'true');
  expect(within(dawnFilters).getByRole('button', { name: 'Albums' })).toHaveAttribute('aria-pressed', 'false');
  expect(screen.getByRole('heading', { name: 'Artists' })).toBeInTheDocument();
});

test('a selected filter whose group vanishes after a refetch falls back to All', async () => {
  const user = userEvent.setup();
  let calls = 0;
  const { queryClient } = renderWideShell({
    path: '/search?q=Night',
    respond: (query) => {
      calls += 1;
      return { body: calls === 1 ? payloadFor(query) : { ...payloadFor(query), albums: [] } };
    }
  });

  expect(await screen.findByRole('heading', { name: 'Results for “Night”' })).toBeInTheDocument();
  const filters = await screen.findByRole('group', { name: 'Search result types' });
  await user.click(within(filters).getByRole('button', { name: 'Albums' }));
  expect(screen.queryByRole('heading', { name: 'Artists' })).not.toBeInTheDocument();

  await act(() => queryClient.invalidateQueries());

  expect(await screen.findByRole('heading', { name: 'Artists' })).toBeInTheDocument();
  const refreshed = await screen.findByRole('group', { name: 'Search result types' });
  expect(within(refreshed).getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'true');
  expect(within(refreshed).queryByRole('button', { name: 'Albums' })).not.toBeInTheDocument();
});
